import { ref, watch, watchEffect, onWatcherCleanup } from 'vue'

const userId = ref(1)
const user = ref(null)

watch(userId, async (id, oldId) => {
  const controller = new AbortController()
  onWatcherCleanup(() => controller.abort())   // runs if id changes again
  try {
    const res = await fetch(`/api/users/${id}`, { signal: controller.signal })
    user.value = await res.json()
  } catch (e) {
    if (e.name !== 'AbortError') throw e
  }
}, { immediate: true })

const theme = ref(localStorage.getItem('theme') ?? 'light')
watchEffect(() => {
  localStorage.setItem('theme', theme.value)   // re-runs when theme changes
  document.documentElement.dataset.theme = theme.value
})

// useFetch.js
import { ref, watchEffect, toValue } from 'vue'

export function useFetch(url) {          // url: string, ref or getter
  const data = ref(null), error = ref(null), loading = ref(false)

  watchEffect(async (onCleanup) => {
    const controller = new AbortController()
    onCleanup(() => controller.abort())
    loading.value = true
    error.value = null
    try {
      const res = await fetch(toValue(url), { signal: controller.signal })
      data.value = await res.json()
    } catch (e) {
      if (e.name !== 'AbortError') error.value = e
    } finally {
      loading.value = false
    }
  })
  return { data, error, loading }
}

