import { ref, shallowRef, triggerRef, markRaw, reactive, toRaw, customRef, effectScope, watchEffect } from 'vue'

const rows = shallowRef(Array.from({ length: 50_000 }, (_, i) => ({ id: i })))
rows.value[0].id = -1         // no update (not tracked deeply)
triggerRef(rows)              // force dependents to update
rows.value = rows.value.slice(0, 10)   // assignment is always tracked

