function debouncedRef(value, ms = 300) {
  let t
  return customRef((track, trigger) => ({
    get() { track(); return value },
    set(v) { clearTimeout(t); t = setTimeout(() => { value = v; trigger() }, ms) },
  }))
}

const scope = effectScope()
scope.run(() => watchEffect(() => console.log(rows.value.length)))   // 10
scope.stop()                  // disposes every effect created in run()

// clickOutside.js
export const vClickOutside = {
  mounted(el, binding) {
    el._onDocClick = (e) => {
      if (!el.contains(e.target)) binding.value(e)   // call the handler
    }
    document.addEventListener('click', el._onDocClick)
  },
  unmounted(el) {
    document.removeEventListener('click', el._onDocClick)
  },
}

