// A toy version of Vue's core idea (the real one adds versions, batching and more)
let activeEffect = null
const deps = new WeakMap()   // target -> Map(key -> Set(effect))

function track(target, key) {
  if (!activeEffect) return
  let m = deps.get(target); if (!m) deps.set(target, (m = new Map()))
  let s = m.get(key); if (!s) m.set(key, (s = new Set()))
  s.add(activeEffect)
}
const trigger = (target, key) => deps.get(target)?.get(key)?.forEach((fn) => fn())
function reactive(obj) {
  return new Proxy(obj, {
    get(t, k, r) { track(t, k); return Reflect.get(t, k, r) },
    set(t, k, v, r) { const ok = Reflect.set(t, k, v, r); trigger(t, k); return ok },
  })
}
function effect(fn) {
  const run = () => { activeEffect = run; try { fn() } finally { activeEffect = null } }
  run()
}

const state = reactive({ n: 1 })
effect(() => console.log('n is', state.n))   // n is 1
state.n = 2                                  // n is 2

import { h, defineComponent, ref } from 'vue'

// A heading whose tag depends on a prop: awkward in a template, easy in a render fn
export const Heading = defineComponent({
  props: { level: { type: Number, default: 1 } },
  setup(props, { slots }) {
    return () => h(`h${props.level}`, { class: 'heading' }, slots.default?.())
  },
})

export const Counter = defineComponent({
  setup() {
    const n = ref(0)
    return () => h('button', { onClick: () => n.value++ }, `Clicked ${n.value}`)
  },
})

