// server.js (Node) - minimal SSR with per-request app creation
import { createSSRApp, ref, h } from 'vue'
import { renderToString } from 'vue/server-renderer'

function createApp() {                 // fresh app per request: no shared state
  return createSSRApp({
    setup() {
      const count = ref(0)
      return () => h('button', { onClick: () => count.value++ }, `Count: ${count.value}`)
    },
  })
}

const html = await renderToString(createApp())
console.log(html)                      // <button>Count: 0</button>

